188	/** Tourism tax report for paid reservations starting in a given month, for the city hall (CSV). */
189	public final class TourismTaxReport {
190	
191	    private static final BigDecimal TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
192	
193	    private final ReservationStore store;
194	
195	    public TourismTaxReport(ReservationStore store) {
196	        this.store = store;
197	    }
198	
199	    public String generate(YearMonth month) {
200	        List<Reservation> paidReservations = new ArrayList<>();
201	        for (Reservation reservation : store.all()) {
202	            boolean paid = reservation.isPaid();
203	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
204	            if (paid && startsInMonth) {
205	                paidReservations.add(reservation);
206	            }
207	        }
208	        paidReservations.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
209	
210	        StringBuilder csv = new StringBuilder();
211	        csv.append(ReportFormat.titleLine("tourism-tax", month.toString()));
212	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
213	        BigDecimal totalTax = BigDecimal.ZERO.setScale(2);
214	        for (Reservation reservation : paidReservations) {
215	            long nights = ChronoUnit.DAYS.between(reservation.checkIn(), reservation.checkOut());
216	            BigDecimal tax = TAX_PER_GUEST_PER_NIGHT
217	                    .multiply(BigDecimal.valueOf(reservation.guests()))
218	                    .multiply(BigDecimal.valueOf(nights));
219	            csv.append(reservation.id()).append(',')
220	                    .append(reservation.roomNumber()).append(',')
221	                    .append(reservation.checkIn()).append(',')
222	                    .append(reservation.checkOut()).append(',')
223	                    .append(reservation.guests()).append(',')
224	                    .append(nights).append(',')
225	                    .append(tax.toPlainString()).append('\n');
226	            totalTax = totalTax.add(tax);
227	        }
228	        csv.append("total,").append(totalTax.toPlainString()).append('\n');
229	        return csv.toString();
230	    }
231	}
